/* ---------- Echo Box gacha (design/gdd/economy-progression.md §10.3 amendment) ----------
   Rarity odds deliberately steep at the top end (product owner: "tỷ lệ vật phẩm hiếm phải
   cực thấp") — mythic is a genuine long-shot, not a soft-pity-guaranteed near-certainty.
   Category is chosen uniformly AFTER rarity, so every rarity roll has an equal chance to
   land in any of the 4 categories (avatar/decor/background/title) before duplicate/fusion
   resolution (see echoBoxOpen() in ui.js). */
const ECHO_BOX_RARITY_ODDS=[0.62,0.27,0.09,0.017,0.003]; // r0..r4, sums to 1.0
const ECHO_BOX_CATEGORIES=['avatar','decor','background','title'];
const COSMETIC_POOLS={avatar:COSMETIC_AVATARS,decor:COSMETIC_DECOR,background:COSMETIC_BACKGROUNDS,title:COSMETIC_TITLES};
/* Fusion (product owner: "ghép các vật phẩm trùng giống để tạo thành vật phẩm tier cao
   hơn"): 3 duplicate rolls of the same rarity — ANY category, not tied to one item — fuse
   into 1 guaranteed-new item one rarity tier up (random category+item within that tier,
   still respecting "don't hand out something already owned" — see fuseCosmetics() in
   ui.js). Mythic (r4) duplicates have nowhere higher to go, so they convert to a flat
   Shard refund instead. */
const ECHO_FUSE_COST=3;
const ECHO_FUSE_MYTHIC_REFUND=250;
